-- Уточнения по проверке Codex (report-recheck2.md): 11 исправлений в 4 вопросах тем 18 и 20, ключи не меняются.
-- Источник: scripts/questions/066_codex_recheck2_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'У службы systemd (cgroup v2) заданы MemoryHigh=1700M и MemoryMax=2G, включён дисковый своп, для службы он не ограничен. Процессу службы нужно 3,6 ГБ активно используемой памяти. Что произойдёт?', NULL, NULL, NULL, 'У службы systemd (cgroup v2) заданы MemoryHigh=1700M и MemoryMax=2G, включён дисковый своп, для службы он не ограничен. Процессу службы нужно 3,6 ГБ активно используемой памяти. Что верно?'),
        ('option', 'У службы systemd (cgroup v2) заданы MemoryHigh=1700M и MemoryMax=2G, включён дисковый своп, для службы он не ограничен. Процессу службы нужно 3,6 ГБ активно используемой памяти. Что верно?', 'Процесс будет завершён по лимиту MemoryMax в момент достижения 2 ГБ', 'MemoryMax ограничивает сумму памяти службы в RAM и в свопе', 'Не сразу: MemoryMax ограничивает учтённую память службы. При нехватке ядро сначала пытается освободить память, в том числе вытеснением в своп (своп учитывается отдельно); если удержать расход в пределах лимита не удаётся, возможен OOM.', 'MemoryMax ограничивает учтённую память службы без свопа: своп учитывается отдельно и ограничивается MemorySwapMax, а здесь он не ограничен. При нехватке ядро сначала пытается освободить память; если удержать расход в пределах лимита не удаётся, возможен OOM.'),
        ('option', 'У службы systemd (cgroup v2) заданы MemoryHigh=1700M и MemoryMax=2G, включён дисковый своп, для службы он не ограничен. Процессу службы нужно 3,6 ГБ активно используемой памяти. Что верно?', 'Служба будет перезапущена systemd, когда процесс достигнет 2 ГБ', 'MemoryMax задаёт systemd политику перезапуска службы после OOM', 'MemoryMax не задаёт автоматический перезапуск. После завершения процесса поведение зависит от настроек службы, в частности Restart; в условии они не указаны.', 'MemoryMax ограничивает память, а не задаёт перезапуск. Что делать после завершения процесса, определяют настройки службы, в частности Restart; в условии они не указаны.'),
        ('option', 'Процесс не использует HugeTLB. У него VmSize равен 439 МБ, VmRSS — 15 МБ, VmSwap — 1 МБ. Что из этого верно?', 'VmSize — 439 МБ, RSS — около 1 МБ, приватные страницы в свопе — около 15 МБ', NULL, 'Значения RSS и свопа перепутаны: в оперативной памяти около 15 МБ, а в свопе около 1 МБ. Большой VmSize сам по себе не признак утечки: адреса резервируются заранее, файлы отображаются целиком.', 'Значения перепутаны: VmRSS показывает около 15 МБ в оперативной памяти, а VmSwap — около 1 МБ приватных анонимных страниц в свопе, без свопа разделяемой памяти.'),
        ('option', 'Какое сочетание условий обычно делает Nested Loop выгодным при соединении по равенству?', 'Когда обе таблицы заранее отсортированы по ключу соединения', 'Оба набора заранее отсортированы по ключу соединения', 'Упорядоченность нужна Merge Join.', NULL),
        ('option', 'Какое сочетание условий обычно делает Nested Loop выгодным при соединении по равенству?', 'Для соединения двух больших таблиц по условию равенства', 'Оба набора велики, а условие соединения — равенство', 'Для больших наборов обычно выгоднее Hash Join.', NULL),
        ('option', 'Какое сочетание условий обычно делает Nested Loop выгодным при соединении по равенству?', 'Оба набора велики, индекса по ключу соединения внутри нет', NULL, 'Без индекса по ключу большая внутренняя таблица читалась бы целиком для каждой внешней строки; при равенстве для таких данных обычно выбирают Hash Join. Nested Loop применяется и при неравенстве, а если соединение задано только неравенством, он единственный вариант.', 'Без пригодного индекса Nested Loop многократно просматривает внутренний набор. Узел Materialize может избавить от повторного чтения таблицы, но не от большого числа проверяемых пар; для двух больших наборов при равенстве обычно выгоднее Hash Join. Nested Loop применяется и при неравенстве, а если соединение задано только неравенством, он единственный вариант.'),
        ('option', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Какой механизм может объяснить такой результат?', 'Во внешней сортировке сравнение идёт по правилам C, а не по ru_RU: это дешевле', 'Переход внешней сортировки с правил ru_RU на правила C', 'Правило сравнения не зависит от способа сортировки.', 'Правило сравнения не зависит от способа сортировки: внешняя сортировка тоже сравнивает по ru_RU.'),
        ('option', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Какой механизм может объяснить такой результат?', 'Внешняя сортировка прочитала строки по индексу id, и сортировать val не пришлось', 'Выдача строк в порядке val через индекс по id', 'Индекс по id не помогает сортировать по val.', NULL),
        ('option', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Какой механизм может объяснить такой результат?', 'Исходный порядок мог сократить число дорогих сравнений при сортировке порций', 'Сокращение числа дорогих сравнений при сортировке упорядоченных порций', 'Если порция уже упорядочена, быстрая сортировка PostgreSQL проверяет это и завершает её одним линейным просмотром; затем порции сливаются отдельно. Это может компенсировать дополнительные затраты внешней сортировки; на перемешанных данных такого преимущества нет.', NULL),
        ('option', 'Строки таблицы вставлены по порядку id, значения val имеют вид «строка 1», «строка 2» и так далее. Сортировка по val с COLLATE "ru_RU.utf8" через диск (external merge) оказалась в два раза быстрее, чем в памяти, а на перемешанной копии таблицы — медленнее. Какой механизм может объяснить такой результат?', 'Чтение временных файлов с диска быстрее, чем чтение тех же данных из памяти', 'Преимущество чтения временных файлов с диска перед чтением из памяти', 'Тогда внешняя сортировка выигрывала бы и на перемешанных данных.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
